param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'span-indexed-access-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult}}
$rows=[Collections.Generic.List[object]]::new();$op=[Reflection.Emit.OpCodes]
foreach($kind in @('Char','Byte','Int32')){$element=[type]::GetType('System.'+$kind,$true);$arrayType=$element.MakeArrayType();$span=switch($kind){'Char'{[type]'System.Span[char]'};'Byte'{[type]'System.Span[byte]'};'Int32'{[type]'System.Span[int]'}};$bridge=[Reflection.Emit.DynamicMethod]::new('Index'+$kind,[object],[type[]]@([Array],[int],[int],[int],[bool],[object]));$il=$bridge.GetILGenerator();$local=$il.DeclareLocal($span);$il.Emit($op::Ldarg_0);$il.Emit($op::Castclass,$arrayType);$il.Emit($op::Ldarg_1);$il.Emit($op::Ldarg_2);$il.Emit($op::Newobj,$span.GetConstructor([type[]]@($arrayType,[int],[int])));$il.Emit($op::Stloc_0);$read=$il.DefineLabel();$il.Emit($op::Ldarg_S,[byte]4);$il.Emit($op::Brfalse,$read);$il.Emit($op::Ldloca_S,$local);$il.Emit($op::Ldarg_3);$il.Emit($op::Call,$span.GetProperty('Item').GetMethod);$il.Emit($op::Ldarg_S,[byte]5);$il.Emit($op::Unbox_Any,$element);$il.Emit($op::Stobj,$element);$il.MarkLabel($read);$il.Emit($op::Ldloca_S,$local);$il.Emit($op::Ldarg_3);$il.Emit($op::Call,$span.GetProperty('Item').GetMethod);$il.Emit($op::Ldobj,$element);$il.Emit($op::Box,$element);$il.Emit($op::Ret);$operation=$bridge.CreateDelegate([Func[Array,int,int,int,bool,object,object]])
 foreach($view in $plan.views){$offset=[int]$view[0];$length=[int]$view[1];$indices=@(-1,0,1,($length-1),$length,[int]::MaxValue)|Sort-Object -Unique;foreach($index in $indices){foreach($write in @($false,$true)){$valuesToWrite=@(0);if($write){$valuesToWrite=$plan.writeValues.PSObject.Properties[$kind].Value};foreach($newValue in $valuesToWrite){$seed=[int[]]$plan.seeds.PSObject.Properties[$kind].Value;switch($kind){'Char'{$values=[char[]]$seed;$value=[char][int]$newValue};'Byte'{$values=[byte[]]$seed;$value=[byte]$newValue};'Int32'{$values=[int[]]$seed.Clone();$value=[int]$newValue}};if($value.GetType() -ne $element){throw 'Input element type mismatch'};try{$actual=$operation.Invoke($values,$offset,$length,$index,$write,$value);$result=[ordered]@{ok=$true;value=[int]$actual}}catch{$result=Failure $_};$rows.Add([ordered]@{kind=$kind;offset=$offset;length=$length;index=$index;write=$write;newValue=[int]$newValue;result=$result;buffer=[int[]]$values})}}}}
}
if($rows.Count -ne $plan.expectedCalls){throw 'Incomplete span index matrix'}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 18 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS span indexed access: $($rows.Count) native calls"
